```java
import java.time.Duration;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Virtual {
    static final Semaphore DB = new Semaphore(10);          // only 10 connections.
    static final AtomicInteger peak = new AtomicInteger(), inUse = new AtomicInteger();

    static void handle(int id) throws InterruptedException {
        Thread.sleep(Duration.ofMillis(50));                  // network wait: cheap on virtual threads.
        DB.acquire();                                         // wait for a connection slot.
        try {
            peak.accumulateAndGet(inUse.incrementAndGet(), Math::max);
            Thread.sleep(Duration.ofMillis(5));               // query.
        } finally {
            inUse.decrementAndGet();
            DB.release();
        }
    }

    public static void main(String[] args) {
        try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {   // closes and waits.
            for (int i = 0; i < 10_000; i++) {
                int id = i;
                exec.submit(() -> { handle(id); return null; });
            }
        }
        System.out.println("peak connections: " + peak.get());   // at most 10
    }
}
```

| Workload | Choose |
|---|---|
| few small steps. | sequential code. |
| CPU-heavy, splittable data. | parallel stream or fixed pool sized to cores. |
| many mostly-blocking tasks. | virtual thread per task. |
| any shared scarce resource. | add a Semaphore or pool limit. |

